//! 🧪️ Actual original input, root and payload allocations survive denied turns and close separately.
use super::*;
use semio_framework_value::{RetainedCloneGrant,advance_retirement_turn};

#[test]
fn original_actor_retirement_binding_preserves_private_source_on_refusal(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🏛️boundary/🔣️.json")).unwrap();let original=&fixture["binding"];let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let input=|operation,generation,epoch|RetainedTurnInput{operation,generation,epoch,grant};let operation=original["operation"].as_u64().unwrap();let generation=original["generation"].as_u64().unwrap();let first=original["firstEpoch"].as_u64().unwrap();let mut slot=OriginalActorContextSlot::empty();let(refusal,heap)=observe(||slot.begin_retirement_input(input(operation,generation,first)));assert_eq!(heap,(0,0));assert_eq!(refusal.unwrap_err().kind,ValueRefusalKind::InvariantViolated);assert!(slot.terminal_is_empty());let(admission,heap)=observe(||slot.admit_step(input(operation,generation,first)));assert_eq!(heap,(0,0));assert_eq!(admission.receipt_spent,RetainedCloneProgress{copied_items:1,..Default::default()});assert!(!admission.result.unwrap().ready);assert_eq!(slot.cancellation_is_cancelled(),None);
 for row in original["cases"].as_array().unwrap(){let supplied=input(row["operation"].as_u64().unwrap(),row["generation"].as_u64().unwrap(),row["epoch"].as_u64().unwrap());let(result,heap)=observe(||slot.begin_retirement_input(supplied));assert_eq!(heap,(0,0));assert_eq!(result.is_ok(),row["accepted"].as_bool().unwrap());if let Err(error)=result{assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);}}
 let mut epoch=22;let mut metadata=0;while !slot.terminal_is_empty(){let(call,heap)=observe(||slot.close_step(input(operation,generation,epoch)));assert_eq!(heap,(0,0));metadata+=call.receipt_spent.copied_items;assert!(call.result.is_ok());epoch+=1;assert!(epoch<26)}assert_eq!(metadata,3);assert_eq!(observe(||drop(slot)).1,(0,0));eprintln!("[DEBUG] Actual General context private binding accepts20/21, refuses foreign/repeated/zero epochs with no mutation, rootaliasbirth or heap; three paid metadata close frontiers and terminalDrop0");
}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_actor_epoch_is_exact_and_cannot_be_rebound_by_a_child(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️epoch.json")).unwrap();let grant=RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let input=|epoch|RetainedTurnInput{operation:fixture["operation"].as_u64().unwrap(),generation:fixture["generation"].as_u64().unwrap(),epoch,grant};let mut owner=OriginalActorContext::new((),input(1)).unwrap();let mut births=0;
 for epoch in 1..=4{let(admission,heap)=observe(||owner.admit_step(input(epoch)).unwrap());births+=heap.0;assert_eq!(heap,(admission.progress.retained_capacity_bytes,0));assert_eq!(admission.ready,epoch==4);}assert_eq!(owner.take_input().unwrap(),Some(()));let mut recipient=RetainedCloneProgress::default();let recipient_identity=&mut recipient as*mut _ as usize;let source=owner.source.as_ref().unwrap()as*const _;let mut last=4;
 for epoch in fixture["epochs"].as_array().unwrap(){let epoch=epoch.as_u64().unwrap();owner.begin_dispatch(input(epoch)).unwrap();let(_,heap)=observe(||{let mut cx=owner.borrow_context(input(epoch),StepBudget::new(100,u64::MAX,grant),&mut recipient,semio_framework_job::logical_now_us).unwrap();assert_eq!(cx.original_source_epoch(),Some(epoch));assert_eq!(cx.original_recipient_identity(),recipient_identity);assert_eq!(cx.original_source_parent().unwrap()as*const _,source);assert!(cx.bind_original_source_epoch(fixture["refusedEpoch"].as_u64().unwrap()).is_err());assert!(cx.bind_original_source_epoch(epoch+1).is_err());assert_eq!(cx.original_source_epoch(),Some(epoch));cx.bind_original_source_epoch(epoch).unwrap();assert_eq!(cx.retained_progress(),RetainedCloneProgress::default());});assert_eq!(heap,(fixture["heapBytes"].as_u64().unwrap()as usize,0));last=epoch;}
 let mut released=0;while !owner.terminal_is_empty(){last+=1;let(step,heap)=observe(||owner.close_step(input(last)).unwrap());assert_eq!(heap,(0,step.progress().released_bytes));released+=heap.1;}assert_eq!(released,births);assert_eq!(observe(||drop(owner)).1,(0,0));eprintln!("[DEBUG] Original actor source epochs=7,9 childRebind=refused heap0 sameRecipient=true sameSource=true rootsReleased={released}");
}
#[test]
fn original_actor_context_preserves_input_and_paid_authorities_across_admission_loans_and_close(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let grant=|key:&str|{let row=&fixture[key];RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize}};let admission=grant("admissionGrant");let body=grant("bodyGrant");let turn=|epoch,grant|RetainedTurnInput{operation:fixture["operation"].as_u64().unwrap(),generation:fixture["generation"].as_u64().unwrap(),epoch,grant};let mut input=Vec::<u8>::with_capacity(fixture["originalInputCapacity"].as_u64().unwrap()as usize);input.extend_from_slice(&[83;41]);let pointer=input.as_ptr();let capacity=input.capacity();assert_eq!(capacity,97);let(mut owner,heap)=observe(||OriginalActorContext::new(input,turn(1,admission)).unwrap());assert_eq!(heap,(0,0));
 let phases=[RetainedCloneGrant{maximum_items:0,..admission},admission,RetainedCloneGrant{maximum_capacity_bytes:0,..admission},admission,RetainedCloneGrant{maximum_capacity_bytes:0,..admission},admission,body];let mut births=0;for(index,grant)in phases.into_iter().enumerate(){let(actual,heap)=observe(||owner.admit_step(turn(index as u64+1,grant)).unwrap());let expected=&fixture["phases"][index];assert_eq!(actual.ready,expected["ready"].as_bool().unwrap());assert_eq!(actual.progress.copied_items,expected["items"].as_u64().unwrap()as usize);assert_eq!(actual.progress.copied_bytes,0);assert_eq!(heap,(actual.progress.retained_capacity_bytes,0));assert_eq!(owner.input().unwrap().as_ptr(),pointer);assert_eq!(owner.input().unwrap().capacity(),capacity);births+=actual.progress.retained_capacity_bytes;if index<6{let(result,heap)=observe(||owner.take_input());assert!(result.is_err());assert_eq!(heap,(0,0));}}
 let parent=owner.source.as_ref().unwrap()as*const _;let(mut original,heap)=observe(||owner.take_input().unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(original.as_ptr(),pointer);assert_eq!(original.capacity(),capacity);let mut recipient=RetainedCloneProgress::default();let recipient_pointer=&mut recipient as*mut _;let mut target=[0;41];let(value,heap)=observe(||{let mut cx=owner.borrow_context(turn(7,body),StepBudget::new(100,u64::MAX,body),&mut recipient,semio_framework_job::logical_now_us).unwrap();assert_eq!(cx.original_source_parent().unwrap()as*const _,parent);unsafe{std::ptr::copy_nonoverlapping(original.as_ptr(),target.as_mut_ptr(),41)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()}).unwrap();cx.retained_progress()});assert_eq!(heap,(0,0));assert_eq!(target,original.as_slice());assert_eq!(value,recipient);assert_eq!(&mut recipient as*mut _,recipient_pointer);assert_eq!(owner.source.as_ref().unwrap()as*const _,parent);let receipt=turn(7,body).return_original(recipient).unwrap();assert_eq!(receipt.remaining.maximum_copy_bytes,4055);
 let(dropped,heap)=observe(||advance_retirement_turn(RetirementDemand{release_bytes:capacity,depth:1,..Default::default()},body,|_|{drop(std::mem::take(&mut original));Ok::<_,ValueError>((RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:capacity,..Default::default()}),true))}).unwrap());assert_eq!(dropped.progress().released_bytes,capacity);assert_eq!(heap,(0,capacity));let mut released=0;let mut steps=0;while !owner.terminal_is_empty(){let(step,heap)=observe(||owner.close_step(turn(8+steps,body)).unwrap());assert_eq!(step.progress().copied_items,1);assert_eq!(step.progress().copied_bytes,0);assert_eq!(heap,(0,step.progress().released_bytes));released+=step.progress().released_bytes;steps+=1;assert!(steps<=16)}assert_eq!(released,births);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original actor71/3 input97 stable={pointer:p} root/payload/source paid births={births} metadata copy0 denied heap0 original recipient={recipient_pointer:p} actual source41 copied once independent release={released} phases={steps} terminalDrop0");
}
